class Solution:
    def maxIncreasingGroups(self, usageLimits: List[int]) -> int:
        usageLimits.sort(reverse=True)
        n = len(usageLimits)

        def can_form(k):
            # Total positions needed for k groups of sizes 1, 2, ..., k
            total_positions = k * (k + 1) // 2

            # If total positions exceeds sum of all usage limits, impossible
            if total_positions > sum(usageLimits):
                return False

            # Check if total capacity is sufficient
            # Each number i can contribute at most min(usageLimits[i], k) to the total count
            total_capacity = sum(min(ul, k) for ul in usageLimits)

            return total_capacity >= total_positions

        # Binary search for the maximum number of groups
        left, right = 0, n
        while left < right:
            mid = (left + right + 1) // 2
            if can_form(mid):
                left = mid
            else:
                right = mid - 1

        return left

